// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlasq6, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 9', function test( t ) {
	t.strictEqual( dlasq6.length, 9, 'returns expected value' );
	t.end();
});

tape( 'the function computes one DQD transform in ping-pong form', function test( t ) {
	var offsetOut;
	var strideOut;
	var expectedZ;
	var expected;
	var strideZ;
	var offsetZ;
	var data;
	var out;
	var I0;
	var N0;
	var PP;
	var Z;

	data = PING;

	I0 = data.I0;
	N0 = data.N0;
	Z = new Float64Array( data.Z );
	strideZ = data.strideZ;
	offsetZ = data.offsetZ;
	PP = data.PP;

	out = new Float64Array( 6 );
	strideOut = data.strideOut;
	offsetOut = data.offsetOut;

	expected = new Float64Array( data.expectedOut );
	expectedZ = new Float64Array( data.Z_out );

	dlasq6( I0, N0, Z, strideZ, offsetZ, PP, out, strideOut, offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Z, expectedZ, 1 ), true, 'returns expected value' );

	data = PONG;

	I0 = data.I0;
	N0 = data.N0;
	Z = new Float64Array( data.Z );
	strideZ = data.strideZ;
	offsetZ = data.offsetZ;
	PP = data.PP;

	out = new Float64Array( 6 );
	strideOut = data.strideOut;
	offsetOut = data.offsetOut;

	expected = new Float64Array( data.expectedOut );
	expectedZ = new Float64Array( data.Z_out );

	dlasq6( I0, N0, Z, strideZ, offsetZ, PP, out, strideOut, offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Z, expectedZ, 1 ), true, 'returns expected value' );
	t.end();
});

